    events.append(event_type)
    return {event_type: list(events)}

def test_load_order_rows_returns_rows_for_owner():
    class FakeCursor:
        def __init__(self):
            self.executed = None
            self.rows = [{"id": 1, "status": "queued", "total": 10.0}]

        def execute(self, query, params=None):
            self.executed = (query, params)

        def fetchall(self):
            return self.rows

    cursor = FakeCursor()
    result = load_order_rows("cust-1", cursor)
    assert result == [{"id": 1, "status": "queued", "total": 10.0}]
    assert cursor.executed[1] == ("cust-1",)

def test_rank_sku_accepts_quantity_at_new_minimum():
    assert rank_sku({"id": "sku-1", "quantity": 5}) == []
    assert rank_sku({"id": "sku-1", "quantity": 4}) == ["quantity below minimum: 4"]

def test_adjust_sku_accepts_quantity_at_new_minimum():
    assert adjust_sku({"id": "sku-1", "quantity": 2}) == []
    assert adjust_sku({"id": "sku-1", "quantity": 1}) == ["quantity below minimum: 1"]

def test_allocate_shipment_accepts_quantity_at_new_minimum():
    assert allocate_shipment({"id": "ship-1", "quantity": 2}) == []
    assert allocate_shipment({"id": "ship-1", "quantity": 1}) == ["quantity below minimum: 1"]

