def test_load_order_rows_uses_parameterized_query():
    class FakeCursor:
        def __init__(self):
            self.params = None

        def execute(self, query, params=()):
            assert "?" in query
            self.params = params

        def fetchall(self):
            return [(1, "queued", 10)]

    cursor = FakeCursor()
    assert load_order_rows("alice", cursor) == [{"id": 1, "status": "queued", "total": 10}]
    assert cursor.params == ("alice",)

def test_cross_check_tariff_routes_empty_inputs():
    assert cross_check_tariff_routes([], [10], ["alpha"]) == {"alpha": 0}
    assert cross_check_tariff_routes(["east"], [], ["alpha"]) == {"alpha": 0}
    assert cross_check_tariff_routes(["east"], [10], []) == {}

